[{"order":1,"type":"heading","text":"Design Patterns: Behavioral (Observer, Strategy, Command)"},{"order":2,"type":"paragraph","text":"Behavioral design patterns focus on communication between objects, identifying common communication patterns and realizing them. This tutorial explores three powerful behavioral patterns in Object-Oriented Programming: Observer, Strategy, and Command."},{"order":3,"type":"subheading","text":"1. The Observer Pattern"},{"order":4,"type":"paragraph","text":"The Observer pattern defines a one-to-many dependency between objects so that when one object changes state, all its dependents are notified and updated automatically. It is heavily used in event-driven architectures."},{"order":5,"type":"code","text":"import java.util.ArrayList;
import java.util.List;

interface Observer {
    void update(String message);
}

class Subject {
    private List<Observer> observers = new ArrayList<>();
    private String state;

    public void attach(Observer observer) {
        observers.add(observer);
    }

    public void setState(String state) {
        this.state = state;
        notifyAllObservers();
    }

    private void notifyAllObservers() {
        for (Observer observer : observers) {
            observer.update(state);
        }
    }
}

class ConcreteObserver implements Observer {
    private String name;
    public ConcreteObserver(String name) { this.name = name; }
    public void update(String message) {
        System.out.println(name + " received state: " + message);
    }
}"},{"order":6,"type":"subheading","text":"2. The Strategy Pattern"},{"order":7,"type":"paragraph","text":"The Strategy pattern enables selecting an algorithm at runtime. Instead of implementing a single algorithm directly, code receives runtime instructions as to which in a family of algorithms to use."},{"order":8,"type":"code","text":"interface PaymentStrategy {
    void pay(int amount);
}

class CreditCardStrategy implements PaymentStrategy {
    public void pay(int amount) {
        System.out.println(amount + " paid with credit card.");
    }
}

class PayPalStrategy implements PaymentStrategy {
    public void pay(int amount) {
        System.out.println(amount + " paid using PayPal.");
    }
}

class ShoppingCart {
    private PaymentStrategy paymentStrategy;
    public void setPaymentStrategy(PaymentStrategy strategy) {
        this.paymentStrategy = strategy;
    }
    public void checkout(int amount) {
        paymentStrategy.pay(amount);
    }
}"},{"order":9,"type":"subheading","text":"3. The Command Pattern"},{"order":10,"type":"paragraph","text":"The Command pattern encapsulates a request as an object, thereby letting you parameterize clients with different requests, queue or log requests, and support undoable operations."},{"order":11,"type":"code","text":"interface Command {
    void execute();
}

class Light {
    public void turnOn() { System.out.println("Light is ON"); }
    public void turnOff() { System.out.println("Light is OFF"); }
}

class TurnOnCommand implements Command {
    private Light light;
    public TurnOnCommand(Light light) { this.light = light; }
    public void execute() { light.turnOn(); }
}

class RemoteControl {
    private Command command;
    public void setCommand(Command command) { this.command = command; }
    public void pressButton() { command.execute(); }
}"},{"order":12,"type":"bullet_point","text":"Use Observer for event handling systems and decoupled state synchronization."},{"order":13,"type":"bullet_point","text":"Use Strategy to avoid massive conditional statements (if-else/switch) for algorithmic variations."},{"order":14,"type":"bullet_point","text":"Use Command for decoupling the object that invokes the operation from the one that knows how to perform it."}]
